"""Generated Markdown view of an implementation record."""
from __future__ import annotations

from typing import Any


def clean(value: Any) -> str:
    return str(value).replace("\n", " ").replace("|", "\\|")


def mark(item: dict[str, Any], action: str) -> str:
    if not item[action]:
        return "no"
    attested = item.get("parent_attested", {}).get(action)
    return f"yes (parent, from {clean(attested['check'])})" if attested else "yes"


def markdown(record: dict[str, Any]) -> str:
    specification = record["specification"]
    lines = [
        "<!-- Generated by spec_tracker.py. Do not edit manually. -->",
        f"# Implementation Record: {record['title']}",
        "",
        f"- Specification: `{specification['path']}`",
        f"- Specification SHA-256: `{specification['sha256']}`",
        f"- Status: {record['status']}",
        f"- Current role: {record['current_role']}",
        f"- Implementation generation: {record.get('generation', 1)}",
        f"- Updated: {record['updated_at']}",
        "",
        "## Requirements",
        "",
        "| ID | Specification reference | Implemented | Tested | Location | Verification |",
        "|---|---|---:|---:|---|---|",
    ]
    for item in record["requirements"]:
        lines.append(
            f"| {item['id']} | {clean(item['spec_ref'])} | {mark(item, 'implemented')} "
            f"| {mark(item, 'tested')} | {clean(item['implementation'])} | {clean(item['verification'])} |"
        )
    if not record["requirements"]:
        lines.append("| — | None | no | no | — | — |")

    lines.extend(["", "## Changed files", ""])
    lines.extend(f"- `{path}`" for path in record["changed_files"])
    if not record["changed_files"]:
        lines.append("- None.")

    lines.extend(["", "## Verification", "", "| Name | Generation | Role | Method | Result | Evidence |", "|---|---:|---|---|---|---|"])
    for item in record["checks"]:
        lines.append(
            f"| {clean(item['name'])} | {item.get('generation', 1)} | {item.get('role', '—')} | {clean(item['method'])} "
            f"| {item['result']} | {clean(item['evidence'])} |"
        )
    if not record["checks"]:
        lines.append("| — | — | — | — | pending | — |")

    retired = record.get("retired_requirements", [])
    if retired:
        lines.extend(["", "## Retired requirements", ""])
        lines.extend(f"- {item['id']} `{clean(item['spec_ref'])}`: {clean(item.get('retirement_reason', 'retired'))}" for item in retired)

    lines.extend(["", "## Bugs", ""])
    if not record["bugs"]:
        lines.append("No bugs reported.")
    for bug in record["bugs"]:
        lines.extend([
            f"### {bug['id']} — {bug['title']}", "",
            f"- Status: {bug['status']}", f"- Severity: {bug['severity']}",
            f"- Specification: {bug['spec_ref']}", f"- Environment: {bug['environment']}",
            f"- Reproduction: {bug['reproduction']}", f"- Expected: {bug['expected']}",
            f"- Actual: {bug['actual']}", f"- Evidence: {bug['evidence']}",
            f"- Assigned fixer: {bug['assigned_fixer'] or 'Unassigned'}",
            f"- Fix: {bug['fix'] or 'Pending'}", f"- Regression verification: {bug['regression'] or 'Pending'}",
            f"- Retest: {bug['retest'] or 'Pending'}", "",
        ])

    lines.extend(["## Specification blockers", ""])
    if not record["blockers"]:
        lines.append("None.")
    for blocker in record["blockers"]:
        status = blocker.get("status", "open")
        resolution = f" Resolution: {blocker['resolution']}" if blocker.get("resolution") else ""
        lines.append(f"- **{blocker['id']}** ({status}) {blocker['summary']} — {blocker['report']}{resolution}")

    gaps = record.get("tool_gaps", [])
    if gaps:
        lines.extend(["", "## Tool gaps", ""])
        for gap in gaps:
            done = f" Tool: {gap['tool']}." if gap.get("tool") else ""
            note = f" {gap['resolution']}" if gap.get("resolution") else ""
            lines.append(f"- **{gap['id']}** ({gap['status']}) `{gap['capability']}` for {', '.join(gap['requirements'])}: {clean(gap['why'])}.{done}{note}")

    plans = record.get("plans", [])
    if plans:
        latest = plans[-1]
        lines.extend(["", "## Plan", "", f"- Version: {latest['version']} (by {latest['added_by']}, {latest['at']}); `tracker plan show {record['feature']}`",
                      f"- Ownership: {', '.join(f'`{glob}`' for glob in latest['ownership'])}"])
        lines.extend(f"- Batch {item['number']}: {clean(item['title'])} ({', '.join(item['requirements'])})" for item in latest["batches"])
    questions = record.get("questions", [])
    if questions:
        lines.extend(["", "## Questions", ""])
        for item in questions:
            reply = f" Answer{' (replan)' if item.get('replan') else ''}: {clean(item['answer'])}" if item.get("answer") else ""
            lines.append(f"- **{item['id']}** ({item['status']}, {item['role']}) {clean(item['text'])}.{reply}")

    history = specification.get("history", [])
    if history:
        lines.extend(["", "## Specification syncs", ""])
        lines.extend(f"- {item['at']}: `{item['previous_sha256'][:12]}` → `{item['sha256'][:12]}` — {item['reason']}" for item in history)

    handoff = record["handoff"]
    lines.extend([
        "", "## Handoff", "",
        f"- Completed work: {handoff['completed'] or 'Not recorded'}",
        f"- Remaining work: {handoff['remaining'] or 'Not recorded'}",
        f"- Checks not run: {handoff['checks_not_run'] or 'None recorded'}",
        f"- Next role: {handoff['next_role'] or 'Not assigned'}",
    ])
    if handoff.get("review_skipped"):
        lines.append("- Review skipped: implementer handed parent-added requirements straight to the tester")
    lines.append("")
    return "\n".join(lines)
